#include <nettle/chacha.h>
#include <nettle/chacha-poly1305.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

typedef struct {
    uint8_t key[32];
    uint8_t nonce[12];
    uint32_t counter;
    size_t length;
    uint8_t *dst;
    const uint8_t *src;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    struct chacha_ctx ctx;
    chacha_set_key(&ctx, j->key);
    chacha_set_nonce96(&ctx, j->nonce);
    uint8_t ctr[4];
    ctr[0] = j->counter & 0xff;
    ctr[1] = (j->counter >> 8) & 0xff;
    ctr[2] = (j->counter >> 16) & 0xff;
    ctr[3] = (j->counter >> 24) & 0xff;
    chacha_set_counter32(&ctx, ctr);
    chacha_crypt32(&ctx, j->length, j->dst, j->src);
    return NULL;
}

int main() {
    size_t n = 40u*1024*1024;
    uint8_t *pt = malloc(n);
    uint8_t *ct = malloc(n);
    uint8_t *ct2 = malloc(n);
    memset(pt, 1, n);
    uint8_t key[32] = {0};
    uint8_t nonce[12] = {0};

    struct chacha_ctx ctx;
    chacha_set_key(&ctx, key);
    chacha_set_nonce96(&ctx, nonce);
    double t0 = now();
    for (int i=0;i<3;i++) {
        chacha_set_key(&ctx, key);
        chacha_set_nonce96(&ctx, nonce);
        chacha_crypt32(&ctx, n, ct, pt);
    }
    double t1 = now();
    printf("chacha_crypt32: %.4f s\n", (t1-t0)/3);

    int nthreads = 6;
    size_t blocks = n/64;
    size_t blocks_per = blocks / nthreads;
    t0 = now();
    for (int rep=0; rep<3; rep++) {
        pthread_t th[16];
        job_t jobs[16];
        size_t off = 0;
        for (int t=0; t<nthreads; t++) {
            size_t b = (t==nthreads-1) ? (blocks-off/64) : blocks_per;
            jobs[t].counter = 1 + (uint32_t)(off/64); /* counter 1 = first data block? we'll verify */
            memcpy(jobs[t].key, key, 32);
            memcpy(jobs[t].nonce, nonce, 12);
            jobs[t].length = b*64;
            jobs[t].dst = ct2+off;
            jobs[t].src = pt+off;
            off += b*64;
            pthread_create(&th[t], NULL, worker, &jobs[t]);
        }
        for (int t=0;t<nthreads;t++) pthread_join(th[t], NULL);
    }
    t1 = now();
    printf("parallel %d threads: %.4f s  match=%d\n", nthreads, (t1-t0)/3, memcmp(ct, ct2, n)==0);

    /* try counter starting at 0 */
    {
        pthread_t th[16]; job_t jobs[16]; size_t off=0;
        for (int t=0;t<nthreads;t++){
            size_t b = (t==nthreads-1)?(blocks-off/64):blocks_per;
            jobs[t].counter = (uint32_t)(off/64);
            memcpy(jobs[t].key,key,32); memcpy(jobs[t].nonce,nonce,12);
            jobs[t].length=b*64; jobs[t].dst=ct2+off; jobs[t].src=pt+off;
            off+=b*64; pthread_create(&th[t],NULL,worker,&jobs[t]);
        }
        for(int t=0;t<nthreads;t++) pthread_join(th[t],NULL);
        printf("counter0 match=%d\n", memcmp(ct,ct2,n)==0);
    }
    return 0;
}
EOF
