#include <openssl/evp.h>

static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
    uint8_t key[32]; uint8_t nonce[12]; uint32_t counter; size_t length;
    uint8_t *dst; const uint8_t *src;
} job_t;

static void *worker(void *arg){
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, NULL, NULL);
    /* ChaCha20 EVP: 16-byte IV = counter(4 LE) || nonce(12) */
    uint8_t iv[16];
    iv[0]=j->counter&0xff; iv[1]=(j->counter>>8)&0xff; iv[2]=(j->counter>>16)&0xff; iv[3]=(j->counter>>24)&0xff;
    memcpy(iv+4, j->nonce, 12);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, iv);
    int outl=0;
    EVP_EncryptUpdate(ctx, j->dst, &outl, j->src, (int)j->length);
    int outl2=0;
    EVP_EncryptFinal_ex(ctx, j->dst+outl, &outl2);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main(){
    size_t n = 40u*1024*1024;
    uint8_t *pt=malloc(n), *ct=malloc(n), *ct2=malloc(n);
    memset(pt,1,n);
    uint8_t key[32]={0}, nonce[12]={0};
    /* serial */
    double t0=now();
    for(int i=0;i<3;i++){
        EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();
        uint8_t iv[16]={0}; memcpy(iv+4,nonce,12); iv[0]=0;
        EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, iv);
        int outl=0; EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        int outl2=0; EVP_EncryptFinal_ex(ctx, ct+outl,&outl2);
        EVP_CIPHER_CTX_free(ctx);
    }
    printf("openssl serial: %.4f\n",(now()-t0)/3);

    for (int nthreads=2; nthreads<=12; nthreads+=2){
        size_t blocks=n/64, blocks_per=blocks/nthreads;
        t0=now();
        for(int rep=0;rep<3;rep++){
            pthread_t th[32]; job_t jobs[32]; size_t off=0;
            for(int t=0;t<nthreads;t++){
                size_t b=(t==nthreads-1)?(blocks-off/64):blocks_per;
                jobs[t].counter=(uint32_t)(off/64);
                memcpy(jobs[t].key,key,32); memcpy(jobs[t].nonce,nonce,12);
                jobs[t].length=b*64; jobs[t].dst=ct2+off; jobs[t].src=pt+off;
                off+=b*64; pthread_create(&th[t],NULL,worker,&jobs[t]);
            }
            for(int t=0;t<nthreads;t++) pthread_join(th[t],NULL);
        }
        printf("threads %d: %.4f match=%d\n", nthreads,(now()-t0)/3, memcmp(ct,ct2,n)==0);
    }
    return 0;
}
