#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
    uint8_t key[32]; uint8_t iv[16]; size_t length;
    uint8_t *dst; const uint8_t *src;
} job_t;

static void *worker(void *arg){
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, j->key, j->iv);
    int outl=0;
    EVP_EncryptUpdate(ctx, j->dst, &outl, j->src, (int)j->length);
    int outl2=0;
    EVP_EncryptFinal_ex(ctx, j->dst+outl, &outl2);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

/* RFC 8439 poly1305 */
typedef struct { uint32_t r[5]; uint32_t h[5]; uint32_t pad[4]; } poly_t;

static void poly_init(poly_t *st, const uint8_t key[32]){
    /* r clamped */
    st->r[0] = (key[0] | (key[1]<<8) | (key[2]<<16) | (key[3]<<24)) & 0x0fffffff;
    st->r[1] = (key[4] | (key[5]<<8) | (key[6]<<16) | (key[7]<<24)) & 0x0ffffffc;
    st->r[2] = (key[8] | (key[9]<<8) | (key[10]<<16) | (key[11]<<24)) & 0x0ffffffc;
    st->r[3] = (key[12] | (key[13]<<8) | (key[14]<<16) | (key[15]<<24)) & 0x0ffffffc;
    st->r[4] = 0;
    memset(st->h, 0, sizeof(st->h));
    st->pad[0] = key[16]|(key[17]<<8)|(key[18]<<16)|(key[19]<<24);
    st->pad[1] = key[20]|(key[21]<<8)|(key[22]<<16)|(key[23]<<24);
    st->pad[2] = key[24]|(key[25]<<8)|(key[26]<<16)|(key[27]<<24);
    st->pad[3] = key[28]|(key[29]<<8)|(key[30]<<16)|(key[31]<<24);
}

static void poly_blocks(poly_t *st, const uint8_t *m, size_t bytes, int final_partial){
    /* process full 16-byte blocks; if final_partial, last block has hibit 0 */
    const uint32_t r0=st->r[0], r1=st->r[1], r2=st->r[2], r3=st->r[3];
    const uint32_t s1=r1*5, s2=r2*5, s3=r3*5, s4=r0*5; /* not used r4 */
    uint32_t h0=st->h[0],h1=st->h[1],h2=st->h[2],h3=st->h[3],h4=st->h[4];
    while (bytes >= 16){
        uint64_t d0 = (uint64_t)(m[0]|(m[1]<<8)|(m[2]<<16)|(m[3]<<24)) + h0;
        uint64_t d1 = (uint64_t)(m[4]|(m[5]<<8)|(m[6]<<16)|(m[7]<<24)) + h1;
        uint64_t d2 = (uint64_t)(m[8]|(m[9]<<8)|(m[10]<<16)|(m[11]<<24)) + h2;
        uint64_t d3 = (uint64_t)(m[12]|(m[13]<<8)|(m[14]<<16)|(m[15]<<24)) + h3;
        uint64_t d4 = h4 + 1; /* hibit */
        /* carry not needed, donna style mul */
        uint64_t t0 = d0*r0 + d1*s3 + d2*s2 + d3*s1 + d4*(r0*5?0:0);
        /* redo properly */
        (void)t0;
        m+=16; bytes-=16;
        /* placeholder to keep compiler quiet - real impl below */
        h0=h0; 
        break;
    }
    st->h[0]=h0;st->h[1]=h1;st->h[2]=h2;st->h[3]=h3;st->h[4]=h4;
}

int main(){
    size_t n = 40u*1024*1024;
    uint8_t *pt=malloc(n), *ct=malloc(n);
    memset(pt,1,n);
    uint8_t key[32]={1}, nonce[12]={2};

    /* full AEAD serial via EVP */
    double t0=now();
    for(int i=0;i<3;i++){
        EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        int outl=0;
        uint8_t aad[32]={3};
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        int outl2=0; EVP_EncryptFinal_ex(ctx, ct+outl, &outl2);
        uint8_t tag[16]; EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        EVP_CIPHER_CTX_free(ctx);
    }
    printf("AEAD serial: %.4f\n",(now()-t0)/3);

    /* chacha20 parallel + serial poly via EVP? measure poly alone by AEAD minus chacha */
    /* measure poly1305 via EVP one-shot? Use EVP_chacha20 for keystream of 32 bytes then time a MAC.
       Instead time AEAD on small vs large to estimate. */
    /* Parallel chacha + we need poly. Let's just time parallel chacha including thread overhead. */
    int nthreads=8;
    uint8_t *ct2=malloc(n);
    size_t blocks=n/64, bper=blocks/nthreads;
    t0=now();
    for(int rep=0;rep<3;rep++){
        pthread_t th[16]; job_t jobs[16]; size_t off=0;
        for(int t=0;t<nthreads;t++){
            size_t b=(t==nthreads-1)?(blocks-off/64):bper;
            memset(jobs[t].iv,0,16);
            uint32_t counter=(uint32_t)(off/64);
            jobs[t].iv[0]=counter&0xff; jobs[t].iv[1]=(counter>>8)&0xff; jobs[t].iv[2]=(counter>>16)&0xff; jobs[t].iv[3]=(counter>>24)&0xff;
            memcpy(jobs[t].iv+4, nonce, 12);
            memcpy(jobs[t].key, key, 32);
            jobs[t].length=b*64; jobs[t].dst=ct2+off; jobs[t].src=pt+off;
            off+=b*64;
            pthread_create(&th[t], NULL, worker, &jobs[t]);
        }
        for(int t=0;t<nthreads;t++) pthread_join(th[t],NULL);
    }
    printf("parallel chacha %d: %.4f\n", nthreads, (now()-t0)/3);

    /* poly1305 speed via openssl EVP MAC? */
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    printf("mac %p\n", (void*)mac);
    if(mac){
        uint8_t pkey[32]={0};
        OSSL_PARAM params[2];
        /* no params */
        EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
        uint8_t tag[16]; size_t taglen=16;
        t0=now();
        for(int i=0;i<3;i++){
            EVP_MAC_init(mctx, pkey, 32, NULL);
            EVP_MAC_update(mctx, pt, n);
            EVP_MAC_final(mctx, tag, &taglen, 16);
        }
        printf("poly1305 serial 40MB: %.4f\n",(now()-t0)/3);
        EVP_MAC_CTX_free(mctx);
    }
    return 0;
}
