#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <openssl/evp.h>

/* low level decls */
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len,
                    const unsigned int key[8], const unsigned int counter[4]);
size_t Poly1305_ctx_size(void);
int Poly1305_Init(void *ctx, const unsigned char key[32]);
int Poly1305_Update(void *ctx, const void *inp, size_t len);
int Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now(){struct timespec ts;clock_gettime(CLOCK_MONOTONIC,&ts);return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct { unsigned char *out; const unsigned char *in; size_t len; unsigned int key[8]; unsigned int counter[4]; } job_t;
static void *wchacha(void *a){ job_t *j=a; ChaCha20_ctr32(j->out,j->in,j->len,j->key,j->counter); return NULL; }

typedef struct { void *ctx; const unsigned char *in; size_t len; } pjob_t;
static void *wpoly(void *a){ pjob_t *j=a; Poly1305_Update(j->ctx, j->in, j->len); return NULL; }

int main(){
    size_t n=40u*1024*1024;
    unsigned char *pt=malloc(n), *ct=malloc(n);
    memset(pt,1,n);
    unsigned int key[8]={1,2,3,4,5,6,7,8};
    unsigned int counter[4]={0,0,0,0};

    double t0=now();
    for(int i=0;i<3;i++) ChaCha20_ctr32(ct, pt, n, key, counter);
    printf("ChaCha20_ctr32 serial: %.4f\n",(now()-t0)/3);

    for(int nt=4; nt<=12; nt+=2){
        size_t blocks=n/64, bper=(blocks/nt)*64;
        t0=now();
        for(int rep=0;rep<3;rep++){
            pthread_t th[16]; job_t jobs[16];
            size_t off=0;
            for(int t=0;t<nt;t++){
                size_t len=(t==nt-1)?(n-off):bper;
                jobs[t].out=ct+off; jobs[t].in=pt+off; jobs[t].len=len;
                memcpy(jobs[t].key,key,32);
                jobs[t].counter[0]=counter[0]+(unsigned)(off/64);
                jobs[t].counter[1]=0; jobs[t].counter[2]=0; jobs[t].counter[3]=0;
                off+=len;
                pthread_create(&th[t],NULL,wchacha,&jobs[t]);
            }
            for(int t=0;t<nt;t++) pthread_join(th[t],NULL);
        }
        printf("chacha threads %d: %.4f\n", nt, (now()-t0)/3);
    }

    size_t csz=Poly1305_ctx_size();
    printf("poly ctx size %zu\n", csz);
    void *pctx=malloc(csz);
    unsigned char pkey[32]={0};
    Poly1305_Init(pctx, pkey);
    unsigned char mac[16];
    t0=now();
    for(int i=0;i<3;i++){ Poly1305_Init(pctx,pkey); Poly1305_Update(pctx,pt,n); Poly1305_Final(pctx,mac); }
    printf("poly serial: %.4f\n",(now()-t0)/3);

    /* parallel independent poly over chunks (not combined) to gauge raw throughput */
    for(int nt=4; nt<=12; nt+=4){
        void *ctxs[16]; for(int t=0;t<nt;t++){ctxs[t]=malloc(csz); Poly1305_Init(ctxs[t],pkey);} 
        size_t chunk=(n/nt)&~15u;
        t0=now();
        for(int rep=0;rep<3;rep++){
            pthread_t th[16]; pjob_t jobs[16];
            for(int t=0;t<nt;t++){
                Poly1305_Init(ctxs[t], pkey);
                jobs[t].ctx=ctxs[t]; jobs[t].in=pt+t*chunk; jobs[t].len=(t==nt-1)?(n-t*chunk):chunk;
                pthread_create(&th[t],NULL,wpoly,&jobs[t]);
            }
            for(int t=0;t<nt;t++) pthread_join(th[t],NULL);
        }
        printf("poly independent threads %d: %.4f\n", nt,(now()-t0)/3);
    }
    return 0;
}
EOF
