typedef unsigned __int128 u128;

static void mul_r(uint64_t *h0, uint64_t *h1, uint64_t *h2, uint64_t r0, uint64_t r1, uint64_t r2){
    /* h = h * r  mod 2^130-5, h2<4, r2<4 */
    u128 r2_5 = (u128)5 * r2;          /* r2 * 5, used for wrap: 2^130 == 5 */
    u128 h0r0 = (u128)(*h0) * r0;
    u128 h0r1 = (u128)(*h0) * r1;
    u128 h0r2 = (u128)(*h0) * r2;
    u128 h1r0 = (u128)(*h1) * r0;
    u128 h1r1 = (u128)(*h1) * r1;
    u128 h1r2_5 = (u128)(*h1) * r2_5;  /* h1*r2*2^128 == h1*r2*5*2^(-2) ... let me redo carefully */

    /* Represent h = h0 + h1*2^64 + h2*2^128, r similarly.
       h*r = h0*r0
           + (h0*r1 + h1*r0) * 2^64
           + (h0*r2 + h1*r1 + h2*r0) * 2^128
           + (h1*r2 + h2*r1) * 2^192
           + (h2*r2) * 2^256
       Reduce using 2^130 == 5, i.e. 2^128 == 4*5? NO: 2^130 = 5 => 2^128 = 5 * 2^(-2) not integer.
       Better: 2^130 ≡ 5 (mod p). So 2^128 ≡ ? not integer power. Use 2^130.
       h*r mod p = low130(h*r) + 5*high(h*r >> 130).
       Let's compute the full product in 3 limbs then reduce. */
    (void)h0r0;(void)h0r1;(void)h0r2;(void)h1r0;(void)h1r1;(void)h1r2_5;
}

/* multiply (h0,h1,h2) by (r0,r1,r2) mod 2^130-5. All *2 < 4. */
static void mul_mod(uint64_t *h0, uint64_t *h1, uint64_t *h2,
                    uint64_t r0, uint64_t r1, uint64_t r2){
    /* Since 2^130 ≡ 5, a term c*2^(128+k) ... let's shift everything to be multiples of 2^64 and reduce at the end
       by the identity: x*2^130 ≡ 5x. */
    u128 p0 = (u128)(*h0)*r0;                         /* 2^0 */
    u128 p1 = (u128)(*h0)*r1 + (u128)(*h1)*r0;        /* 2^64 */
    u128 p2 = (u128)(*h0)*r2 + (u128)(*h1)*r1 + (u128)(*h2)*r0; /* 2^128 */
    u128 p3 = (u128)(*h1)*r2 + (u128)(*h2)*r1;        /* 2^192 */
    u128 p4 = (u128)(*h2)*r2;                         /* 2^256 */

    /* fold p3*2^192 = p3*2^62 * 2^130 ≡ p3*2^62 * 5
       fold p4*2^256 = p4*2^126 * 2^130 ≡ p4*2^126 * 5
       fold p2*2^128 = p2*2^128; the part of p2 above 2 bits contributes via 2^130. */
    /* Add folded p3 into p0 (bits 0..63 of 5*p3<<62) and p1 (rest). 5*p3 << 62:
       5*p3 is up to 5*2*2^64 = 10*2^64, fits in ~68 bits. <<62 => up to bit 130. */
    u128 f3 = (u128)5 * p3;          /* < 2^70 */
    u128 f4 = (u128)5 * p4;          /* < 2^7 */
    /* 5*p3*2^62 contributes to bit positions starting at 62 */
    p0 += f3 << 62;                  /* may overflow u128? f3<<62 < 2^132, so use wider handling */
}

int main(){
    size_t csz=Poly1305_ctx_size();
    unsigned char key[32]; for(int i=0;i<32;i++) key[i]=i*7+3;
    unsigned char *ctx=calloc(1,csz);
    Poly1305_Init(ctx,key);
    uint64_t r0,r1,r2;
    memcpy(&r0, ctx+24, 8); memcpy(&r1, ctx+32, 8); memcpy(&r2, ctx+40, 8);
    printf("r0=%llx r1=%llx r2=%llx\n", (unsigned long long)r0,(unsigned long long)r1,(unsigned long long)r2);

    unsigned char msg[64]; for(int i=0;i<64;i++) msg[i]=i*3+1;
    /* h after 1 block */
    Poly1305_Init(ctx,key);
    Poly1305_Update(ctx,msg,16);
    uint64_t h0,h1,h2; memcpy(&h0,ctx,8); memcpy(&h1,ctx+8,8); memcpy(&h2,ctx+16,8);
    printf("h(1 block): %llx %llx %llx\n",(unsigned long long)h0,(unsigned long long)h1,(unsigned long long)h2);

    /* manually compute expected h for one block: (n + 2^128) * r mod p, where n is the 16 bytes LE */
    uint64_t n0,n1; memcpy(&n0,msg,8); memcpy(&n1,msg+8,8);
    /* hibit: add 1 at bit 128 => h2 starts at 1 before multiply? The addition of the block happens
       then multiply by r. So input to multiply is (n0, n1, 1). */
    /* We'll compute (n0 + n1*2^64 + 1*2^128) * r mod (2^130-5) and compare. */
    /* Use python-free big int via __int128 carefully with reduction. */
    /* Full product of 130-bit * 130-bit fits in 260 bits: use array of u128 limbs at 2^64. */
    uint64_t a0=n0,a1=n1,a2=1;
    /* product limbs q[i] at 2^(64i), i=0..4, each q fits in u128 (< 3 * 2^128) */
    u128 q0 = (u128)a0*r0;
    u128 q1 = (u128)a0*r1 + (u128)a1*r0;
    u128 q2 = (u128)a0*r2 + (u128)a1*r1 + (u128)a2*r0;
    u128 q3 = (u128)a1*r2 + (u128)a2*r1;
    u128 q4 = (u128)a2*r2;
    /* normalize carries to get canonical 64-bit limbs l0..l4 */
    uint64_t l0=(uint64_t)q0; u128 c=q0>>64;
    q1+=c; uint64_t l1=(uint64_t)q1; c=q1>>64;
    q2+=c; uint64_t l2=(uint64_t)q2; c=q2>>64;
    q3+=c; uint64_t l3=(uint64_t)q3; c=q3>>64;
    q4+=c; uint64_t l4=(uint64_t)q4; c=q4>>64;
    uint64_t l5=(uint64_t)c;
    /* value = l0 + l1*2^64 + l2*2^128 + l3*2^192 + l4*2^256 + l5*2^320
       Reduce: 2^130 ≡ 5. Write value = low130 + 5*high, where high = value >> 130.
       low130 = l0 + (l1 bits 0..63)*2^64 + (l2 bottom 2 bits)*2^128
       high = (l2>>2) + l3*2^62 + l4*2^126 + l5*2^190 */
    uint64_t lo0=l0, lo1=l1, lo2=l2 & 3;
    /* high = (l2>>2) + l3<<62 + l4<<126 + l5<<190. Compute 5*high and add to low. */
    /* 5*high = 5*(l2>>2) + 5*l3*2^62 + 5*l4*2^126 + 5*l5*2^190 */
    u128 t0 = (u128)5*(l2>>2);
    u128 t1 = (u128)5*l3;   /* <<62 */
    u128 t2 = (u128)5*l4;   /* <<126 = <<62 then <<64 */
    u128 t3 = (u128)5*l5;   /* <<190 = <<62 then <<128 */
    u128 z0 = (u128)lo0 + t0 + (t1<<62);
    u128 z1 = (u128)lo1 + (t1>>2) + (t2<<62) + (z0>>64);  /* t1>>2 = top of t1<<62? wait recompute */
    (void)z1;(void)t3;
    printf("debug l: %llx %llx %llx %llx %llx %llx\n",
        (unsigned long long)l0,(unsigned long long)l1,(unsigned long long)l2,
        (unsigned long long)l3,(unsigned long long)l4,(unsigned long long)l5);
    return 0;
}
