static const u128 P = (((u128)1) << 130) - 5;

static u128 r_key;          /* poly1305 r for current key */
static int key_ready;

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    unsigned int counter0;
    unsigned int key[8];
    unsigned int ctr_nonce[3];
    /* poly */
    const unsigned char *mac_in;
    size_t mac_len;
