    }
    if (j->do_poly){
        size_t csz = Poly1305_ctx_size();
        void *ctx = j->out; /* reuse? no, separate - use stack buffer via malloc */
    }
    return NULL;
}

/* poly worker with its own ctx buffer */
typedef struct {
    const unsigned char *data;
    size_t len;
    unsigned char polykey[32];
    u128 h;
    unsigned char ctxbuf[256];
} pjob_t;

static void *pworker(void *arg){
    pjob_t *j = arg;
    Poly1305_Init(j->ctxbuf, j->polykey);
    Poly1305_Update(j->ctxbuf, j->data, j->len);
    /* read h: 3 limbs, partially reduced so h < 2^130 + small; take mod P */
    uint64_t h0,h1,h2;
