    memcpy(&h1, j->ctxbuf+8, 8);
    memcpy(&h2, j->ctxbuf+16, 8);
    u128 H = (u128)h0 + ((u128)h1 << 64) + ((u128)h2 << 128);
    j->h = H % P;
    return NULL;
}

/* r^(n) mod P via binary exponentiation, n = number of blocks */
static u128 powmod(u128 base, uint64_t exp){
    u128 result = 1;
