               Split: (a_hi*2^128 + a_lo) * (b_hi*2^128 + b_lo) */
            u128 a = result, b = base;
            u128 alo = (uint64_t)a, ahi = (uint64_t)(a>>64);
            /* a is 131 bits: ahi fits in 67 bits */
            u128 blo = (uint64_t)b, bhi = (uint64_t)(b>>64);
