            u128 p0 = alo * blo;                 /* bits 0..127 */
            u128 p1 = alo * bhi;                 /* bits 64.. */
            u128 p2 = ahi * blo;                 /* bits 64.. */
            u128 p3 = ahi * bhi;                 /* bits 128.. */
            uint64_t l0 = (uint64_t)p0;
