    size_t hdr_len = 0;
    if (aad_len){ memcpy(hdr, aad, aad_len); hdr_len = aad_len; if (aad_pad){ memset(hdr+aad_len,0,aad_pad); hdr_len += aad_pad; } }

    size_t csz = Poly1305_ctx_size();
    unsigned char ctxbuf[256];
    Poly1305_Init(ctxbuf, otk);
    if (hdr_len) Poly1305_Update(ctxbuf, hdr, hdr_len);
    uint64_t hh0,hh1,hh2;
    memcpy(&hh0, ctxbuf, 8); memcpy(&hh1, ctxbuf+8, 8); memcpy(&hh2, ctxbuf+16, 8);
    u128 h_header = ((u128)hh0) + ((u128)hh1<<64) + ((u128)hh2<<128);
    h_header %= P;

    /* parallel poly over ciphertext chunks (must be 16-byte aligned; our chunks are 64-aligned except last) */
    int pn = nt;
    size_t poff = 0;
    pthread_t pth[MAX_THREADS];
    size_t plen_base = (pt_len/64/pn)*64;
    for (int t=0;t<pn;t++){
        size_t len = (t==pn-1)?(pt_len-poff):plen_base;
