        pjobs[t].data = ct+poff;
        size_t full = len & ~(size_t)15;
        pjobs[t].len = full;
        memcpy(pjobs[t].polykey, otk, 32);
        pthread_create(&pth[t], NULL, pworker, &pjobs[t]);
        poff += len;
    }
    for (int t=0;t<pn;t++) pthread_join(pth[t], NULL);

    /* combine: acc = h_header; for each chunk: acc = acc * r^{nblocks} + h_chunk */
    u128 r = 0;
    {
        uint64_t r0,r1,r2;
        /* r lives in the ctx after Init */
        memcpy(&r0, ctxbuf+24, 8); memcpy(&r1, ctxbuf+32, 8); memcpy(&r2, ctxbuf+40, 8);
        r = (u128)r0 + ((u128)r1<<64) + ((u128)r2<<128);
