    poff = 0;
    for (int t=0;t<pn;t++){
        size_t len = (t==pn-1)?(pt_len-poff):plen_base;
        size_t full = len & ~(size_t)15;
        uint64_t nb = full/16;
        if (nb){
            acc = (acc * powmod(r, nb) + pjobs[t].h) % P;
        }
