    uint64_t r0,r1,r2;
    memcpy(&r0, mainctx+24, 8); memcpy(&r1, mainctx+32, 8); memcpy(&r2, mainctx+40, 8);
    u128 r = (u128)r0 + ((u128)r1<<64) + (((u128)r2)<<64<<64);

    /* parallel poly over ct chunks; chunks are 64-aligned except the last */
    pthread_t pth[MAX_THREADS];
    pjob_t pjobs[MAX_THREADS];
    size_t plen_base = bper*64;
    size_t poff = 0;
    for (int t=0;t<nt;t++){
        size_t len = (t==nt-1)?(pt_len-poff):plen_base;
        size_t full = len & ~(size_t)15;
        pjobs[t].data = ct+poff;
        pjobs[t].len = full;
        memcpy(pjobs[t].polykey, otk, 32);
        pthread_create(&pth[t], NULL, pworker, &pjobs[t]);
        poff += len;
    }
    for (int t=0;t<nt;t++) pthread_join(pth[t], NULL);

    u128 acc = h_header;
    poff = 0;
    for (int t=0;t<nt;t++){
        size_t len = (t==nt-1)?(pt_len-poff):plen_base;
        size_t full = len & ~(size_t)15;
        uint64_t nb = full/16;
        if (nb) acc = addmod(mulmod(acc, powmod(r, nb)), pjobs[t].h);
        poff += len;
    }

    /* write acc back and finish tail + length block */
    uint64_t o0=(uint64_t)acc, o1=(uint64_t)(acc>>64), o2=(uint64_t)((acc>>64)>>64);
    memcpy(mainctx, &o0, 8); memcpy(mainctx+8, &o1, 8); memcpy(mainctx+16, &o2, 8);
    /* clear the partial-block counter (offset 0xe0) to be safe */
    memset(mainctx+0xe0, 0, 8);

    size_t tail = pt_len & 15;
    if (tail){
        unsigned char tmp[16]; memset(tmp,0,16);
        memcpy(tmp, ct+(pt_len-tail), tail);
        Poly1305_Update(mainctx, tmp, 16);
    }
    unsigned char lens[16];
    uint64_t al = aad_len, cl = pt_len;
    memcpy(lens, &al, 8); memcpy(lens+8, &cl, 8);
    Poly1305_Update(mainctx, lens, 16);
    Poly1305_Final(mainctx, tag);
    return 0;
}

int main(){
