    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC,&ts); double t0=ts.tv_sec+ts.tv_nsec*1e-9;
    for(int i=0;i<3;i++) aead_encrypt(key,nonce,pt,n,aad,32,ct,tag);
    clock_gettime(CLOCK_MONOTONIC,&ts); double t1=ts.tv_sec+ts.tv_nsec*1e-9;
    printf("parallel aead: %.4f\n",(t1-t0)/3);

