    /* add (l2&3)*2^128 = (l2&3) placed at bits 128..129, i.e. into the top of a 128-bit word: bit (128-64)=64 of the high half.
       Represent low as 130 bits: lo64=l0, hi = l1 + (l2&3)<<64, but (l2&3)<<64 overflows u64. Keep as u128 plus a 2-bit top. */
    uint64_t top2 = l2 & 3;                 /* bits 128..129 */
    /* high = product >> 130 = (l2>>2) + l3<<62 + l4<<126 */
    u128 high = (u128)(l2>>2) + ((u128)l3<<62) + ((u128)l4<<62<<64);
    uint64_t hlo=(uint64_t)high, hhi=(uint64_t)(high>>64);
    u128 f0 = (u128)hlo * 5;                /* 5*high low */
    u128 f1 = (u128)hhi * 5 + (f0>>64);     /* 5*high bits 64.. */
    /* res = low + 5*high, low = l0 + l1*2^64 + top2*2^128 */
    u128 s0 = (u128)l0 + (uint64_t)f0;
    u128 s1 = (u128)l1 + (uint64_t)f1 + (s0>>64);
    u128 s2 = (u128)top2 + (f1>>64) + (s1>>64);   /* bits 128.. */
    uint64_t R0=(uint64_t)s0, R1=(uint64_t)s1, R2=(uint64_t)s2;
    /* second reduction: value = R0 + R1*2^64 + R2*2^128 */
    uint64_t top2b = R2 & 3;
    u128 high2 = (u128)(R2>>2);
    u128 t0 = (u128)R0 + (uint64_t)(high2*5);
    u128 t1 = (u128)R1 + (uint64_t)((high2*5)>>64) + (t0>>64);
    u128 t2 = (u128)top2b + (t1>>64);
