    /* Let's just rebuild from R0,R1,R2 directly with a final canonical reduction loop. */
    (void)out;
    /* Final: start from (R0, R1, top2=R2&3) and add 5*(R2>>2), iterating until top < 4 and value < P. */
    uint64_t A0=R0, A1=R1; uint64_t A2=R2;
    for (int iter=0; iter<3; iter++){
        uint64_t newtop = A2 & 3;
        u128 hv = (u128)(A2>>2);
        u128 g0 = (u128)A0 + (uint64_t)(hv*5);
        u128 g1 = (u128)A1 + ((hv*5)>>64) + (g0>>64);
