static u128 addmod(u128 a, u128 b){
    u128 P = ((((u128)1)<<66)<<64) - 5;
    u128 s = a + b;
    if (s >= P || s < a) s -= P;
    return s;
}

static u128 powmod(u128 base, uint64_t exp){
