    while (exp){
        if (exp & 1) result = mulmod(result, base);
        exp >>= 1;
        if (exp) base = mulmod(base, base);
    }
    return result;
}

/* load accumulator (3 limbs, possibly slightly over-reduced) and reduce mod P */
static u128 load_h(const unsigned char *ctx){
    uint64_t h0,h1,h2;
    memcpy(&h0, ctx, 8); memcpy(&h1, ctx+8, 8); memcpy(&h2, ctx+16, 8);
    /* h2 holds bits 128.. and possibly a couple more. value = h0 + h1*2^64 + h2*2^128 */
    uint64_t A0=h0, A1=h1; uint64_t A2=(uint64_t)h2;
    for (int iter=0; iter<3; iter++){
        uint64_t newtop = A2 & 3;
        u128 hv = (u128)(A2>>2);
