    return res;
}

typedef struct {
    const unsigned char *in; unsigned char *out; size_t len;
    unsigned int counter0; unsigned int key[8]; unsigned int cn[3];
} cjob_t;

static void *cworker(void *arg){
    cjob_t *j = arg;
    unsigned int counter[4] = {j->counter0, j->cn[0], j->cn[1], j->cn[2]};
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, counter);
    return NULL;
}

typedef struct {
    const unsigned char *data; size_t len;
    unsigned char polykey[32]; u128 h; unsigned char ctxbuf[512];
} pjob_t;

static void *pworker(void *arg){
    pjob_t *j = arg;
    Poly1305_Init(j->ctxbuf, j->polykey);
    if (j->len) Poly1305_Update(j->ctxbuf, j->data, j->len);
    j->h = load_h(j->ctxbuf);
    return NULL;
}

static int g_nthreads = 8;

int aead_encrypt(const unsigned char *key, const unsigned char *nonce,
                 const unsigned char *pt, size_t pt_len,
                 const unsigned char *aad, size_t aad_len,
                 unsigned char *ct, unsigned char tag[16]){
    unsigned int k[8]; memcpy(k, key, 32);
    unsigned int cn[3]; memcpy(cn, nonce, 12);

    unsigned char otk[64], zeros[64]; memset(zeros,0,64);
    unsigned int counter0[4] = {0, cn[0], cn[1], cn[2]};
    ChaCha20_ctr32(otk, zeros, 64, k, counter0);

    int nt = g_nthreads;
    if (pt_len < (size_t)nt * 4096) nt = 1;
    size_t blocks64 = pt_len / 64;
    size_t bper = blocks64 / nt;

    pthread_t cth[MAX_THREADS]; cjob_t cjobs[MAX_THREADS];
    size_t off = 0;
    for (int t=0; t<nt; t++){
        size_t len = (t==nt-1) ? (pt_len-off) : bper*64;
        cjobs[t].in=pt+off; cjobs[t].out=ct+off; cjobs[t].len=len;
        cjobs[t].counter0 = 1 + (unsigned)(off/64);
        memcpy(cjobs[t].key, k, 32); memcpy(cjobs[t].cn, cn, 12);
        off += len;
        pthread_create(&cth[t], NULL, cworker, &cjobs[t]);
    }
    for (int t=0;t<nt;t++) pthread_join(cth[t], NULL);

    size_t aad_pad = (16 - (aad_len & 15)) & 15;
    unsigned char hdr[64]; size_t hdr_len = 0;
    if (aad_len){ memcpy(hdr, aad, aad_len); hdr_len = aad_len; }
    if (aad_pad){ memset(hdr+hdr_len, 0, aad_pad); hdr_len += aad_pad; }

    unsigned char mainctx[512];
    Poly1305_Init(mainctx, otk);
    if (hdr_len) Poly1305_Update(mainctx, hdr, hdr_len);
    u128 h_header = load_h(mainctx);

    uint64_t r0,r1; memcpy(&r0, mainctx+24, 8); memcpy(&r1, mainctx+32, 8);
    u128 r = (u128)r0 + ((u128)r1<<64);

    pthread_t pth[MAX_THREADS]; pjob_t pjobs[MAX_THREADS];
    size_t plen_base = bper*64, poff = 0;
    for (int t=0;t<nt;t++){
        size_t len = (t==nt-1)?(pt_len-poff):plen_base;
        pjobs[t].data = ct+poff;
        pjobs[t].len = len & ~(size_t)15;
        memcpy(pjobs[t].polykey, otk, 32);
        pthread_create(&pth[t], NULL, pworker, &pjobs[t]);
        poff += len;
    }
    for (int t=0;t<nt;t++) pthread_join(pth[t], NULL);

    u128 acc = h_header;
    poff = 0;
    for (int t=0;t<nt;t++){
        size_t len = (t==nt-1)?(pt_len-poff):plen_base;
        size_t full = len & ~(size_t)15;
        if (full) acc = addmod(mulmod(acc, powmod(r, full/16)), pjobs[t].h);
        poff += len;
    }

    uint64_t o0=(uint64_t)acc, o1=(uint64_t)(acc>>64); uint64_t o2=0;
    memcpy(mainctx, &o0, 8); memcpy(mainctx+8, &o1, 8); memcpy(mainctx+16, &o2, 8);
    memset(mainctx+0xe0, 0, 8);

    size_t tail = pt_len & 15;
    if (tail){
        unsigned char tmp[16]; memset(tmp,0,16);
        memcpy(tmp, ct+(pt_len-tail), tail);
        Poly1305_Update(mainctx, tmp, 16);
    }
    unsigned char lens[16];
    uint64_t al=aad_len, cl=pt_len;
    memcpy(lens, &al, 8); memcpy(lens+8, &cl, 8);
