int main(){
    size_t n = 40u*1024*1024;
    unsigned char *pt=malloc(n), *ct=malloc(n);
    memset(pt,0x5a,n);
    unsigned char key[32], nonce[12], aad[32];
    for(int i=0;i<32;i++) key[i]=i;
    for(int i=0;i<12;i++) nonce[i]=i+3;
    for(int i=0;i<32;i++) aad[i]=i*2;
