#include <stdio.h>
#include <stdint.h>
#include <string.h>
typedef unsigned __int128 u128;

/* 130-bit field element: 3 x 64-bit limbs, value = l0 + l1*2^64 + l2*2^128, kept < 2^132 */
typedef struct { uint64_t l[3]; } fe;

static fe fe_from_u128(u128 v){ fe r; r.l[0]=(uint64_t)v; r.l[1]=(uint64_t)(v>>64); r.l[2]=0; return r; }

/* reduce so l2 < 4 (i.e. value < 2^130) and then < P */
static void fe_reduce(fe *a){
    for (int i=0;i<3;i++){
        uint64_t top = a->l[2] & 3;
        u128 hv = (u128)(a->l[2] >> 2);
        u128 f = hv * 5;
        u128 s0 = (u128)a->l[0] + (uint64_t)f;
        u128 s1 = (u128)a->l[1] + (f>>64) + (s0>>64);
        a->l[0]=(uint64_t)s0; a->l[1]=(uint64_t)s1;
        a->l[2]= top + (uint64_t)(s1>>64);
    }
    /* now l2 is 0..3 and tiny; if value >= P, subtract P */
    u128 P_hi_check = (u128)a->l[2];
    if (a->l[2] > 3 || (a->l[2]==3 && (a->l[1] > 0xFFFFFFFFFFFFFFFFULL || (a->l[1]==0xFFFFFFFFFFFFFFFFULL && a->l[0]>=(uint64_t)-5)))){
        /* value >= 2^130-5. subtract P = 2^130 - 5 => add 5, subtract 2^130 (which is l2-=4) */
        u128 s0 = (u128)a->l[0] + 5;
        u128 s1 = (u128)a->l[1] + (s0>>64);
        a->l[0]=(uint64_t)s0; a->l[1]=(uint64_t)s1;
        a->l[2]= a->l[2] + (uint64_t)(s1>>64) - 4;
    }
    (void)P_hi_check;
}

static fe fe_add(fe a, fe b){
    u128 s0=(u128)a.l[0]+b.l[0];
    u128 s1=(u128)a.l[1]+b.l[1]+(s0>>64);
    u128 s2=(u128)a.l[2]+b.l[2]+(s1>>64);
    fe r; r.l[0]=(uint64_t)s0; r.l[1]=(uint64_t)s1; r.l[2]=(uint64_t)s2;
    fe_reduce(&r);
    return r;
}

static fe fe_mul(fe a, fe b){
    uint64_t L[6]={0,0,0,0,0,0};
    for(int i=0;i<3;i++) for(int j=0;j<3;j++){
        u128 p = (u128)a.l[i]*b.l[j];
        int k=i+j; u128 carry=p;
        while(carry){ u128 s=(u128)L[k]+(uint64_t)carry; L[k]=(uint64_t)s; carry=(carry>>64)+(s>>64); k++; }
    }
    /* fold: 2^130 ≡ 5 => limb2 contributes (L2>>2)*5 at bit 0 and (L2&3) stays;
       limb3: 2^192 = 2^62 * 2^130 ≡ 5*2^62
       limb4: 2^256 = 2^126 * 2^130 ≡ 5*2^126
       limb5: 2^320 = 2^190 * 2^130 ≡ 5*2^190 */
    u128 fold = (u128)(L[2]>>2) + ((u128)L[3]<<62) + ((u128)L[4]<<62<<64) + ((u128)L[5]<<62<<64<<64);
    /* fold fits in ~ 2^128 + a bit. 5*fold in two parts */
    uint64_t flo=(uint64_t)fold, fhi=(uint64_t)(fold>>64);
    /* also bits of fold above 128: fold may exceed 128 bits (L5 term). recompute fold as 192-bit. */
    /* L5 is tiny (product of two <2^66 values gives L5 < 2^8). Handle L5 separately: 5*L5*2^190 = 5*L5*2^62 * 2^128 */
    u128 fold_lo = (u128)(L[2]>>2) + ((u128)L[3]<<62) + ((u128)L[4]<<62<<64); /* < 2^128 + 2^126 + 2^124 < 2^129 */
    uint64_t flo2=(uint64_t)fold_lo, fhi2=(uint64_t)(fold_lo>>64);
    u128 extra = (u128)L[5]*5; /* *2^190 = *2^62 * 2^128 */
    /* 5*fold = (flo2 + fhi2*2^64)*5 + extra*2^190 */
    u128 g0 = (u128)flo2*5;
    u128 g1 = (u128)fhi2*5 + (g0>>64);
    u128 g2 = (g1>>64);
    /* add extra*5? extra already is 5*L5. extra*2^190 contributes to bits 190.. => limb index: bit 190 = limb 2 (128) + bit 62 */
    u128 e0 = (extra<<62);          /* goes to bits 190..253 -> position bit 128+62, so add to g2 shifted 62 */
    g2 += (extra<<62);
    (void)e0;
    fe r;
    u128 s0 = (u128)L[0] + (uint64_t)g0;
    u128 s1 = (u128)L[1] + (uint64_t)g1 + (s0>>64);
    u128 s2 = (u128)(L[2] & 3) + (uint64_t)g2 + (g1>>64) + (s1>>64);
    r.l[0]=(uint64_t)s0; r.l[1]=(uint64_t)s1; r.l[2]=(uint64_t)s2;
    fe_reduce(&r);
    return r;
}

static fe fe_pow(fe base, uint64_t e){
    fe r = fe_from_u128(1);
    while(e){ if(e&1) r=fe_mul(r,base); e>>=1; if(e) base=fe_mul(base,base); }
    return r;
}

static void show(const char *l, fe v){ printf("%s %llx %llx %llx\n", l,(unsigned long long)v.l[2],(unsigned long long)v.l[1],(unsigned long long)v.l[0]); }

int main(){
    unsigned char data[16]; for(int i=0;i<16;i++) data[i]=(i*3)&0xff;
    uint64_t n0,n1; memcpy(&n0,data,8);memcpy(&n1,data+8,8);
    fe block; block.l[0]=n0; block.l[1]=n1; block.l[2]=1;
    unsigned char rb[16]={0xff,0xff,0xff,0x0f,0xfc,0xff,0xff,0x0f,0xfc,0xff,0xff,0x0f,0xfc,0xff,0xff,0x0f};
    uint64_t r0,r1; memcpy(&r0,rb,8);memcpy(&r1,rb+8,8);
    fe r; r.l[0]=r0; r.l[1]=r1; r.l[2]=0;
    fe m = fe_mul(block, r);
    show("result", m);
    /* expected 0x27177d226b0adff4acbc0084ac2aded28 */
    return 0;
}
