    u128 g2=(g1>>64) + (((u128)L[5]*5)<<62);
    fe r;
    u128 s0=(u128)L[0]+(uint64_t)g0;
    u128 s1=(u128)L[1]+(uint64_t)g1+(s0>>64);
    u128 s2=(u128)(L[2]&3)+(uint64_t)g2+(g1>>64)+(s1>>64);
    r.l[0]=(uint64_t)s0; r.l[1]=(uint64_t)s1; r.l[2]=(uint64_t)s2;
    fe_reduce(&r); return r;
}

static fe fe_pow(fe base, uint64_t e){
    fe r; r.l[0]=1; r.l[1]=0; r.l[2]=0;
    while (e){ if (e&1) r=fe_mul(r,base); e>>=1; if (e) base=fe_mul(base,base); }
    return r;
}

/* Convert the accumulator OpenSSL left in a Poly1305 context into a reduced field element.
   is_base2_26 flag lives at byte offset 0x14. */
static fe load_h(const unsigned char *ctx){
    fe r;
    if (ctx[0x14] == 0){
        uint64_t h0,h1,h2;
        memcpy(&h0, ctx, 8); memcpy(&h1, ctx+8, 8); memcpy(&h2, ctx+16, 8);
        r.l[0]=h0; r.l[1]=h1; r.l[2]=h2;
    } else {
        uint32_t d[5];
        memcpy(d, ctx, 20);
        /* h = d0 + d1*2^26 + d2*2^52 + d3*2^78 + d4*2^104 */
        u128 lo = (u128)d[0] + ((u128)d[1]<<26) + ((u128)d[2]<<52);
        u128 hi = ((u128)d[2]>>12) + ((u128)d[3]<<14) + ((u128)d[4]<<40); /* bits 64+ */
        r.l[0]=(uint64_t)lo;
        u128 l1 = (lo>>64) + (uint64_t)hi;
        r.l[1]=(uint64_t)l1;
        r.l[2]=(uint64_t)(l1>>64) + (uint64_t)(hi>>64);
    }
    fe_reduce(&r);
    return r;
}

typedef struct {
    const unsigned char *in; unsigned char *out; size_t len;
    unsigned int counter0; unsigned int key[8]; unsigned int cn[3];
} cjob_t;
static void *cworker(void *arg){
    cjob_t *j=arg;
    unsigned int counter[4]={j->counter0, j->cn[0], j->cn[1], j->cn[2]};
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, counter);
    return NULL;
}

typedef struct {
    const unsigned char *data; size_t len; unsigned char polykey[32];
    fe h; unsigned char ctxbuf[512];
} pjob_t;
static void *pworker(void *arg){
    pjob_t *j=arg;
    Poly1305_Init(j->ctxbuf, j->polykey);
    if (j->len) Poly1305_Update(j->ctxbuf, j->data, j->len);
    j->h = load_h(j->ctxbuf);
    return NULL;
}

static int g_nthreads = 8;

int aead_encrypt(const unsigned char *key, const unsigned char *nonce,
                 const unsigned char *pt, size_t pt_len,
                 const unsigned char *aad, size_t aad_len,
                 unsigned char *ct, unsigned char tag[16]){
    unsigned int k[8]; memcpy(k, key, 32);
    unsigned int cn[3]; memcpy(cn, nonce, 12);

    unsigned char otk[64], zeros[64]; memset(zeros,0,64);
    unsigned int c0[4]={0, cn[0], cn[1], cn[2]};
    ChaCha20_ctr32(otk, zeros, 64, k, c0);

    int nt = g_nthreads;
    if (pt_len < (size_t)nt*4096) nt = 1;
    size_t bper = (pt_len/64) / nt;

    pthread_t cth[MAX_THREADS]; cjob_t cjobs[MAX_THREADS];
    size_t off=0;
    for (int t=0;t<nt;t++){
        size_t len=(t==nt-1)?(pt_len-off):bper*64;
        cjobs[t].in=pt+off; cjobs[t].out=ct+off; cjobs[t].len=len;
        cjobs[t].counter0=1+(unsigned)(off/64);
        memcpy(cjobs[t].key,k,32); memcpy(cjobs[t].cn,cn,12);
        off+=len;
        pthread_create(&cth[t], NULL, cworker, &cjobs[t]);
    }
    for (int t=0;t<nt;t++) pthread_join(cth[t], NULL);

    size_t aad_pad=(16-(aad_len&15))&15;
    unsigned char hdr[64]; size_t hdr_len=0;
    if (aad_len){ memcpy(hdr,aad,aad_len); hdr_len=aad_len; }
    if (aad_pad){ memset(hdr+hdr_len,0,aad_pad); hdr_len+=aad_pad; }

    unsigned char mainctx[512];
    Poly1305_Init(mainctx, otk);
    if (hdr_len) Poly1305_Update(mainctx, hdr, hdr_len);
    fe h_header = load_h(mainctx);

    uint64_t r0,r1; memcpy(&r0, mainctx+24, 8); memcpy(&r1, mainctx+32, 8);
    fe r; r.l[0]=r0; r.l[1]=r1; r.l[2]=0;

    pthread_t pth[MAX_THREADS]; pjob_t pjobs[MAX_THREADS];
    size_t plen_base=bper*64, poff=0;
    for (int t=0;t<nt;t++){
        size_t len=(t==nt-1)?(pt_len-poff):plen_base;
        pjobs[t].data=ct+poff; pjobs[t].len=len & ~(size_t)15;
        memcpy(pjobs[t].polykey, otk, 32);
        pthread_create(&pth[t], NULL, pworker, &pjobs[t]);
        poff+=len;
    }
    for (int t=0;t<nt;t++) pthread_join(pth[t], NULL);

    fe acc = h_header;
    poff=0;
    for (int t=0;t<nt;t++){
        size_t len=(t==nt-1)?(pt_len-poff):plen_base;
        size_t full=len & ~(size_t)15;
        if (full) acc = fe_add(fe_mul(acc, fe_pow(r, full/16)), pjobs[t].h);
        poff+=len;
    }

    /* write the reduced accumulator back in base 2^64 form and finish */
    uint64_t z=0;
    memcpy(mainctx, &acc.l[0], 8);
    memcpy(mainctx+8, &acc.l[1], 8);
    memcpy(mainctx+16, &acc.l[2], 8);
    mainctx[0x14]=0;                      /* is_base2_26 = 0 */
    memset(mainctx+0xe0, 0, 8);           /* no partial block buffered */

    size_t tail=pt_len & 15;
    if (tail){
        unsigned char tmp[16]; memset(tmp,0,16);
        memcpy(tmp, ct+(pt_len-tail), tail);
        Poly1305_Update(mainctx, tmp, 16);
    }
    unsigned char lens[16];
    uint64_t al=aad_len, cl=pt_len;
    memcpy(lens,&al,8); memcpy(lens+8,&cl,8);
    Poly1305_Update(mainctx, lens, 16);
    Poly1305_Final(mainctx, tag);
    (void)z;
    return 0;
}

static double now(void){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    size_t n=40u*1024*1024;
    unsigned char *pt=malloc(n), *ct=malloc(n), *ct2=malloc(n+16);
    memset(pt,0x5a,n);
    unsigned char key[32], nonce[12], aad[32];
    for(int i=0;i<32;i++) key[i]=i;
    for(int i=0;i<12;i++) nonce[i]=i+3;
    for(int i=0;i<32;i++) aad[i]=i*2;
    unsigned char tag[16], tag2[16];

    double t0=now();
    for(int i=0;i<3;i++) aead_encrypt(key,nonce,pt,n,aad,32,ct,tag);
    printf("parallel aead: %.4f\n",(now()-t0)/3);

    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
    int outl=0; EVP_EncryptUpdate(c, NULL, &outl, aad, 32);
    EVP_EncryptUpdate(c, ct2, &outl, pt, (int)n);
    int outl2=0; EVP_EncryptFinal_ex(c, ct2+outl, &outl2);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    EVP_CIPHER_CTX_free(c);
    printf("40MB ct %d tag %d\n", memcmp(ct,ct2,n)==0, memcmp(tag,tag2,16)==0);
    if(memcmp(tag,tag2,16)){ printf("ours "); for(int i=0;i<16;i++) printf("%02x",tag[i]); printf("\n");
        printf("evp  "); for(int i=0;i<16;i++) printf("%02x",tag2[i]); printf("\n"); }

    /* odd length, empty aad */
    size_t n2=1000003;
    aead_encrypt(key,nonce,pt,n2,NULL,0,ct,tag);
    c=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(c, ct2, &outl, pt, (int)n2);
    EVP_EncryptFinal_ex(c, ct2+outl, &outl2);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    EVP_CIPHER_CTX_free(c);
    printf("odd ct %d tag %d\n", memcmp(ct,ct2,n2)==0, memcmp(tag,tag2,16)==0);

    /* aad not multiple of 16 */
    unsigned char aad2[7]={1,2,3,4,5,6,7};
    aead_encrypt(key,nonce,pt,n2,aad2,7,ct,tag);
    c=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(c, NULL, &outl, aad2, 7);
    EVP_EncryptUpdate(c, ct2, &outl, pt, (int)n2);
    EVP_EncryptFinal_ex(c, ct2+outl, &outl2);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    EVP_CIPHER_CTX_free(c);
    printf("aad7 ct %d tag %d\n", memcmp(ct,ct2,n2)==0, memcmp(tag,tag2,16)==0);

    /* tiny */
    aead_encrypt(key,nonce,pt,10,aad2,7,ct,tag);
    c=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c, EVP_chacha20_poly1305(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(c, NULL, &outl, aad2, 7);
    EVP_EncryptUpdate(c, ct2, &outl, pt, 10);
    EVP_EncryptFinal_ex(c, ct2+outl, &outl2);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_AEAD_GET_TAG, 16, tag2);
    EVP_CIPHER_CTX_free(c);
    printf("tiny ct %d tag %d\n", memcmp(ct,ct2,10)==0, memcmp(tag,tag2,16)==0);
    return 0;
}
